var n=`1049-opor-ayam`;var t=`world-1049`;var a=`ID`;var s=`southeast-asia`;var r=4;var o=54;var l={en:`Opor Ayam`,ua:`Опор аям`};var g={en:`Opor Ayam is a dish from Indonesia prepared with shallot, garlic, chicken thigh, coconut milk. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Опор аям, страва кухні країни Індонезія, яку готують із таких продуктів: цибуля шалот, часник, куряче стегно, кокосове молоко. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var h=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 7 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 7 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:7,i:[[`shallot`,150,`g`],[`garlic`,4,`clove`],[`ground-coriander`,7,`g`],[`ground-turmeric`,6,`g`],[`canola-oil`,35,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 40 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 40 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:40,i:[[`chicken-thigh`,900,`g`],[`coconut-milk`,650,`ml`],[`lemongrass`,2,`pcs`],[`makrut-lime-leaves`,4,`leaf`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:4,i:[[`palm-sugar`,28,`g`],[`table-salt`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,22,`g`]]}];var d={slug:n,id:t,country:`ID`,region:s,servings:4,minutes:54,title:l,text:g,steps:h};export{a as country,d as default,t as id,o as minutes,s as region,r as servings,n as slug,h as steps,g as text,l as title};